package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;

/** Actual WAV/storage/UI, injected review output only. Never creates MediaPlayer or AudioRecord. */
public class SoundLibraryUiTest {
    @org.junit.Rule public final SoundBrowseTestScope browseScope=new SoundBrowseTestScope();
    static final class FakePort implements ClipPlaybackPort {
        final List<FakeSession> sessions=new java.util.concurrent.CopyOnWriteArrayList<>();volatile boolean closed;
        public ClipReviewPlayer.Session open(ClipReviewPlayer.Target value,ClipReviewPlayer.Events events){FakeSession session=new FakeSession((ClipTarget)value,events);sessions.add(session);new Handler(Looper.getMainLooper()).post(events::ready);return session;}
        public void close(){closed=true;for(FakeSession s:sessions)s.close();}public boolean awaitClosed(long timeout){return closed;}
    }
    static final class FakeSession implements ClipReviewPlayer.Session {
        final ClipTarget target;final ClipReviewPlayer.Events events;volatile int plays,closes;volatile long seek;
        FakeSession(ClipTarget target,ClipReviewPlayer.Events events){this.target=target;this.events=events;}
        public void play(long position){plays++;events.playing();events.position(position);}
        public void pause(){events.paused();}public void seek(long value){seek=value;events.position(value);}public void close(){closes++;}
    }
    private File wave(Context c,List<File> files)throws Exception{File dir=new File(c.getFilesDir(),"clips");assertTrue(dir.isDirectory()||dir.mkdirs());File file=new File(dir,"verification-player-"+UUID.randomUUID()+".wav");byte[] pcm=new byte[320000];for(int n=0;n<160000;n++){short sample=(short)(Math.sin(n*.12)*(2000+(n/5000%9)*2500));pcm[n*2]=(byte)sample;pcm[n*2+1]=(byte)(sample>>8);}NoiseRecorder.writeWave(file,pcm);files.add(file);return file;}
    private void capture(UiDevice device,File folder,String name)throws Exception{device.waitForIdle();assertTrue(device.takeScreenshot(new File(folder,name+".png")));}
    private void recreateEvents(Instrumentation instrumentation,List<Activity> owned){instrumentation.runOnMainSync(()->{for(Activity activity:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(activity instanceof SoundEventsActivity){owned.add(activity);activity.recreate();}});}
    private int playRequests(List<FakePort> ports){int requests=0;for(FakePort port:ports)for(FakeSession session:port.sessions)requests+=session.plays;return requests;}
    static void chooseOneDayAndApply(UiDevice device){
        UiObject2 row=device.wait(Until.findObject(By.text("Keep recordings").enabled(true)),5000);assertNotNull("Retention row is ready",row);row.click();
        UiObject2 day=device.wait(Until.findObject(By.desc("1 day")),3000);assertNotNull("One-day choice is visible",day);day.click();
        // Choosing rebuilds the Activity content after dismissing the dialog. Wait for the
        // selected value on the page, then resolve the newly attached Save button.
        assertTrue("Day chooser dismissed",device.wait(Until.gone(By.desc("1 day")),3000));
        assertTrue("Draft is one day",device.wait(Until.hasObject(By.text("1 day")),3000));
        UiObject2 save=device.wait(Until.findObject(By.text("Save & apply retention").enabled(true)),3000);assertNotNull("Retention Save is attached and enabled",save);save.click();
    }
    private ClipSeekView seek(View root){if(root instanceof ClipSeekView)return (ClipSeekView)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int n=0;n<group.getChildCount();n++){ClipSeekView found=seek(group.getChildAt(n));if(found!=null)return found;}}return null;}
    @Test public void recordedIntervalsFavoritesAndDeletionPersistWithFakePlaybackOnly()throws Exception{
        Instrumentation i=InstrumentationRegistry.getInstrumentation();Context c=i.getTargetContext();org.junit.Assume.assumeTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));org.junit.Assume.assumeTrue(InstrumentationRegistry.getArguments().getString("ciReview","").equals("true"));
        UiDevice device=UiDevice.getInstance(i);String database="sleepwell-verification-"+UUID.randomUUID()+".db";Records.Factory before=Records.factory;ClipPlayback.Provider provider=ClipPlayback.provider;List<Activity> owned=new ArrayList<>();List<FakePort> ports=new java.util.concurrent.CopyOnWriteArrayList<>();List<File> files=new ArrayList<>();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());long id;String firstKey,speechKey;
        try{
            try(Store store=new Store(c,database)){id=store.begin();long start=store.rows("SELECT start FROM sessions").get(0).getLong("start");File first=wave(c,files),second=wave(c,files);store.clip(id,start+10000,first.getName(),.2,10000);store.clip(id,start+20000,second.getName(),.2,10000);store.soundEvent(id,start+1000,1950,"snoring",.9,null);store.soundEvent(id,start+4500,1950,"snoring",.9,null);store.soundEvent(id,start+12000,1950,"speech",.9,null);store.soundEvent(id,start+25000,1950,"snoring",.9,null);store.end(id,false,30000,start+30000);List<org.json.JSONObject> events=store.rows("SELECT * FROM sound_events ORDER BY time");firstKey="event:"+events.get(0).getLong("id");speechKey="event:"+events.get(2).getLong("id");}
            i.runOnMainSync(()->{Records.factory=context->new Store(context,database);ClipPlayback.provider=(context,factory)->{FakePort fake=new FakePort();ports.add(fake);return fake;};});long session=id;
            i.runOnMainSync(()->c.startActivity(new Intent(c,SoundEventsActivity.class).putExtra("record",session).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic WAVs · fake playback output").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));
            assertTrue(device.wait(Until.hasObject(By.desc("Play "+firstKey)),5000));assertTrue(ports.get(0).sessions.isEmpty());assertTrue(device.hasObject(By.text("Audio not recorded")));capture(device,folder,"library-recordings");
            device.findObject(By.desc("Play "+firstKey)).click();assertTrue(device.wait(Until.hasObject(By.desc("Pause "+firstKey)),3000));FakeSession first=ports.get(0).sessions.get(0);assertEquals(1000,first.target.fromMs);assertEquals(1950,first.target.durationMs);assertEquals(1,first.plays);capture(device,folder,"library-playback");
            i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof SoundEventsActivity){ClipSeekView view=seek(a.getWindow().getDecorView());assertNotNull(view);Bundle args=new Bundle();args.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,900);assertTrue(view.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),args));}});assertEquals(900,first.seek);
            device.findObject(By.desc("Pause "+firstKey)).click();assertTrue(device.wait(Until.hasObject(By.desc("Play "+firstKey)),3000));device.findObject(By.desc("Favorite "+firstKey)).click();assertTrue(device.wait(Until.hasObject(By.desc("Unfavorite "+firstKey).selected(true)),5000));
            i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof SoundEventsActivity){owned.add(a);a.recreate();}});assertTrue(device.wait(Until.hasObject(By.desc("Unfavorite "+firstKey).selected(true)),5000));assertTrue(device.hasObject(By.desc("Play "+firstKey)));assertTrue(ports.get(1).sessions.isEmpty());capture(device,folder,"library-favorite-recreated");
            device.findObject(By.desc("Speech (1)")).click();assertTrue(device.wait(Until.hasObject(By.desc("Play "+speechKey)),5000));device.findObject(By.desc("Play "+speechKey)).click();assertTrue(device.wait(Until.hasObject(By.desc("Pause "+speechKey)),3000));FakeSession speech=ports.get(1).sessions.get(0);assertEquals(2000,speech.target.fromMs);assertEquals(1950,speech.target.durationMs);capture(device,folder,"library-speech");
            device.findObject(By.desc("All (4)")).click();assertTrue(device.wait(Until.hasObject(By.desc("Delete "+firstKey)),5000));device.findObject(By.desc("Delete "+firstKey)).click();assertTrue(device.wait(Until.hasObject(By.text("Delete recording")),3000));device.findObject(By.text("Delete recording")).click();assertTrue(device.wait(Until.gone(By.desc("Play "+firstKey)),5000));assertTrue(device.wait(Until.hasObject(By.text("Audio not recorded")),5000));assertFalse(files.get(0).exists());
            try(Store store=new Store(c,database)){assertEquals(4,store.rows("SELECT id FROM sound_events").size());assertEquals(1,store.rows("SELECT favorite FROM sound_events ORDER BY time").get(0).getInt("favorite"));assertEquals(1,store.rows("SELECT id FROM clips").size());assertEquals(3,store.rows("SELECT id FROM sound_events WHERE clip IS NULL").size());}capture(device,folder,"library-recording-deleted");
            int requests=playRequests(ports);
            device.findObject(By.desc("Sound event options")).click();assertTrue(device.wait(Until.hasObject(By.desc("All events").selected(true)),3000));assertTrue(device.hasObject(By.text("Analysis details")));capture(device,folder,"library-options");
            recreateEvents(i,owned);assertTrue(device.wait(Until.hasObject(By.desc("All events").selected(true)),5000));assertEquals("Restoring Options must not replay audio",requests,playRequests(ports));capture(device,folder,"library-options-recreated");
            device.findObject(By.text("Analysis details")).click();assertTrue(device.wait(Until.hasObject(By.text("Got it")),3000));assertTrue(device.hasObject(By.textContains("Waveforms appear only when recorded audio is still available.")));capture(device,folder,"library-analysis-details");
            recreateEvents(i,owned);assertTrue(device.wait(Until.hasObject(By.text("Got it")),5000));assertTrue(device.hasObject(By.textContains("Waveforms appear only when recorded audio is still available.")));assertEquals("Restoring Analysis details must not replay audio",requests,playRequests(ports));capture(device,folder,"library-analysis-details-recreated");
            device.findObject(By.text("Got it")).click();assertTrue(device.wait(Until.gone(By.text("Got it")),3000));recreateEvents(i,owned);assertTrue(device.wait(Until.hasObject(By.desc("All (4)").selected(true)),5000));assertFalse("A dismissed dialog must stay dismissed",device.hasObject(By.text("Got it")));assertFalse(device.hasObject(By.desc("All events")));assertEquals(requests,playRequests(ports));
        }catch(Throwable failure){try{capture(device,folder,"library-failure");device.dumpWindowHierarchy(new File(folder,"library-failure.xml"));}catch(Throwable diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{i.runOnMainSync(()->{for(Stage stage:Stage.values())if(stage!=Stage.DESTROYED)for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(stage))if(a instanceof SoundEventsActivity&&!owned.contains(a))owned.add(a);for(Activity a:owned)a.finish();});i.waitForIdleSync();boolean drained=false;try{for(Activity a:owned)assertTrue(((SoundEventsActivity)a).awaitReaders(5000));drained=true;}finally{i.runOnMainSync(()->{Records.factory=before;ClipPlayback.provider=provider;});if(drained){c.deleteDatabase(database);for(File file:files)if(file.exists())assertTrue(file.delete());}}}
    }
    @Test public void savingRetentionActuallyPrunesOnlyExpiredUnfavoritedAudio()throws Exception{
        Instrumentation i=InstrumentationRegistry.getInstrumentation();Context c=i.getTargetContext();org.junit.Assume.assumeTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));org.junit.Assume.assumeTrue(InstrumentationRegistry.getArguments().getString("ciReview","").equals("true"));
        UiDevice device=UiDevice.getInstance(i);String database="sleepwell-verification-"+UUID.randomUUID()+".db";Records.Factory before=Records.factory;List<Activity> owned=new ArrayList<>();List<File> files=new ArrayList<>();String[] keys={"audioRetentionDays","keepAudioFavorites","audioRetentionError"};Map<String,?> preferences=Prefs.of(c).getAll();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());
        try{
            try(Store store=new Store(c,database)){long start=System.currentTimeMillis()-2*86400000L;store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,source,zone) VALUES(1,?,?,'tracked','UTC')",new Object[]{start,start+30000});File favorite=wave(c,files),expired=wave(c,files);store.clip(1,start+10000,favorite.getName(),.2,10000);store.clip(1,start+20000,expired.getName(),.2,10000);store.soundEvent(1,start+1000,1950,"snoring",.9,null);SoundClips.favoriteEvent(store,store.rows("SELECT * FROM sound_events").get(0),true);}
            i.runOnMainSync(()->{Records.factory=context->new Store(context,database);Prefs.put(c,"audioRetentionDays",7);Prefs.put(c,"keepAudioFavorites",true);c.startActivity(new Intent(c,SoundLibrarySettingsActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic retention fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));});
            chooseOneDayAndApply(device);assertTrue(device.wait(Until.hasObject(By.text("Retention saved.")),5000));assertEquals(1,Prefs.number(c,"audioRetentionDays",0));assertTrue(files.get(0).exists());assertFalse(files.get(1).exists());try(Store store=new Store(c,database)){assertEquals(1,store.rows("SELECT id FROM clips").size());assertEquals(1,store.rows("SELECT id FROM sound_events WHERE favorite=1 AND clip IS NOT NULL").size());}capture(device,folder,"library-retention-applied");
            i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof SoundLibrarySettingsActivity){owned.add(a);a.recreate();}});assertTrue(device.wait(Until.hasObject(By.text("1 day")),5000));assertTrue(device.hasObject(By.desc("Keep favorites").checked(true)));capture(device,folder,"library-retention-recreated");
        }catch(Throwable failure){try{capture(device,folder,"library-retention-policy-failure");device.dumpWindowHierarchy(new File(folder,"library-retention-policy-failure.xml"));}catch(Throwable diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{i.runOnMainSync(()->{for(Stage stage:Stage.values())if(stage!=Stage.DESTROYED)for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(stage))if(a instanceof SoundLibrarySettingsActivity&&!owned.contains(a))owned.add(a);for(Activity a:owned)a.finish();});i.waitForIdleSync();boolean drained=false;try{for(Activity a:owned)assertTrue(((SoundLibrarySettingsActivity)a).awaitReaders(5000));drained=true;}finally{i.runOnMainSync(()->{Records.factory=before;android.content.SharedPreferences.Editor edit=Prefs.of(c).edit();for(String key:keys){edit.remove(key);Object value=preferences.get(key);if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof String)edit.putString(key,(String)value);}assertTrue(edit.commit());});if(drained){c.deleteDatabase(database);for(File file:files)if(file.exists())assertTrue(file.delete());}}}
    }
}
